#include <iostream>

enum class Operation { Addition = 1, Subtraction = 2, Multiplication = 3, Mixed = 4 };

int computeMaxBound(int difficulty) {
    int bound = 0;
    for (int i = 0; i < difficulty; ++i) {
        bound = bound * 10 + 9;
    }
    return bound;
}

struct SimpleRng {
    unsigned int state;
    int nextInt(int minVal, int maxVal) {
        state = state * 1103515245U + 12345U;
        unsigned int range = static_cast<unsigned int>(maxVal - minVal + 1);
        return minVal + static_cast<int>((state / 65536U) % range);
    }
};

int main() {
    SimpleRng rng{42U};
    int difficulty = 1;
    int maxVal = computeMaxBound(difficulty);

    constexpr int totalQuestions = 4;
    int correctCount = 0;

    for (int i = 0; i < totalQuestions; ++i) {
        int a = rng.nextInt(1, maxVal);
        int b = rng.nextInt(1, maxVal);
        int opCode = 3; // Multiplication mode

        int expected = 0;
        char symbol = '*';
        if (opCode == 1) {
            symbol = '+';
            expected = a + b;
        } else if (opCode == 2) {
            symbol = '-';
            expected = a - b;
        } else {
            symbol = '*';
            expected = a * b;
        }

        std::cout << "Q" << (i + 1) << ": How much is " << a << " " << symbol << " " << b << "?\n";

        int studentAnswer = 0;
        if (!(std::cin >> studentAnswer)) {
            break;
        }

        if (studentAnswer == expected) {
            std::cout << "Correct!\n";
            ++correctCount;
        } else {
            std::cout << "Wrong answer.\n";
        }
    }

    double percentage = (static_cast<double>(correctCount) / totalQuestions) * 100.0;
    std::cout << "Score: " << percentage << "%\n";

    if (percentage >= 75.0) {
        std::cout << "Congratulations, you are ready to go to the next level!\n";
    } else {
        std::cout << "Please ask your teacher for extra help.\n";
    }

    return 0;
}
